body.script:
window.jQuery || document.write('<\/script>')


$(".quick-search").keyup(function () {
    var filter = $(this).val(), count = 0;
    $(".country-item", $(this).closest('.panel-body')).each(function () {
        if ($(this).text().search(new RegExp(filter, "i")) < 0) {
            $(this).hide();
        } else {
            $(this).show();
            count++;
        }
    });    
});
$('.collapse').collapse()
